using System.Security.Claims;
using LinfishAppcation.Data;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Npgsql;

namespace LinfishAppcation.Controllers;

[ApiController,Route("api/admin/after-sales"),Authorize(Roles="admin")]
// 2026-11-27：售後檢查改以訂單 stat 判斷取消狀態。
public sealed class AfterSalesController(AppDbContext db):ControllerBase
{
 private NpgsqlConnection Connection=>(NpgsqlConnection)db.Database.GetDbConnection();
 public sealed record LineInput(long OrderItemId,int Quantity);
 public sealed record CaseInput(long OrderId,string? Reason,decimal RefundAmount,List<LineInput>? Items);
 public sealed record StatusInput(string? Status);

 [HttpGet("order/{orderId:long}")]
 public async Task<IActionResult> List(long orderId,CancellationToken ct){await Connection.OpenAsync(ct);await using var cmd=new NpgsqlCommand("select a.id,a.reason,a.status,a.refund_amount,a.cre_date,u.usr_name,a.received_at,receiver.usr_name,a.refunded_at,refunder.usr_name from cmepms.after_sale a join cmbase.ogcusr u on u.id=a.created_by left join cmbase.ogcusr receiver on receiver.id=a.received_by left join cmbase.ogcusr refunder on refunder.id=a.refunded_by where a.order_id=@id order by a.id desc",Connection);cmd.Parameters.AddWithValue("id",orderId);var cases=new List<(long Id,string Reason,string Status,decimal Amount,DateTime Created,string By,DateTime? Received,string? ReceivedBy,DateTime? Refunded,string? RefundedBy)>();await using(var r=await cmd.ExecuteReaderAsync(ct)){while(await r.ReadAsync(ct))cases.Add((r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetDecimal(3),r.GetDateTime(4),r.GetString(5),r.IsDBNull(6)?null:r.GetDateTime(6),r.IsDBNull(7)?null:r.GetString(7),r.IsDBNull(8)?null:r.GetDateTime(8),r.IsDBNull(9)?null:r.GetString(9)));}var result=new List<object>();foreach(var a in cases){await using var lines=new NpgsqlCommand("select x.id,x.order_item_id,x.quantity,x.restocked_at,i.product_name,i.sku_name from cmepms.after_sale_item x join cmepms.order_item i on i.id=x.order_item_id where x.after_sale_id=@id order by x.id",Connection);lines.Parameters.AddWithValue("id",a.Id);await using var r=await lines.ExecuteReaderAsync(ct);var items=new List<object>();while(await r.ReadAsync(ct))items.Add(new{id=r.GetInt64(0),orderItemId=r.GetInt64(1),quantity=r.GetInt32(2),restockedAt=r.IsDBNull(3)?(DateTime?)null:r.GetDateTime(3),productName=r.GetString(4),skuName=r.GetString(5)});result.Add(new{id=a.Id,reason=a.Reason,status=a.Status,refundAmount=a.Amount,createdAt=a.Created,createdBy=a.By,receivedAt=a.Received,receivedBy=a.ReceivedBy,refundedAt=a.Refunded,refundedBy=a.RefundedBy,items});}return Ok(result);}

 [HttpPost]
 public async Task<IActionResult> Create(CaseInput input,CancellationToken ct)
 {
  if(!Guid.TryParse(User.FindFirstValue("sub"),out var admin))return Unauthorized();var reason=input.Reason?.Trim();var items=input.Items??[];
  if(input.OrderId<=0||string.IsNullOrWhiteSpace(reason)||reason.Length>2000||input.RefundAmount<0||input.RefundAmount>9999999999.99m||decimal.Round(input.RefundAmount,2)!=input.RefundAmount||items.Count>100||items.Any(x=>x.OrderItemId<=0||x.Quantity<=0)||items.Select(x=>x.OrderItemId).Distinct().Count()!=items.Count)return BadRequest(new{message="請檢查售後原因、退款金額與商品數量。"});
  await Connection.OpenAsync(ct);await using var tx=await Connection.BeginTransactionAsync(ct);
  await using var order=new NpgsqlCommand("select total_amount,exists(select 1 from cmepms.payment p where p.order_id=o.id and p.payment_status='PAID'),coalesce(stat,'') from cmepms.orders o where id=@id for update",Connection,tx);order.Parameters.AddWithValue("id",input.OrderId);decimal total;bool paid;await using(var r=await order.ExecuteReaderAsync(ct)){if(!await r.ReadAsync(ct))return NotFound();total=r.GetDecimal(0);paid=r.GetBoolean(1);if(r.GetString(2)=="ZZ")return Conflict(new{message="訂單已取消，不能新增售後紀錄。"});}if(!paid)return Conflict(new{message="尚未確認付款，無法建立付款後售後紀錄。"});
  await using var prior=new NpgsqlCommand("select coalesce(sum(refund_amount),0) from cmepms.after_sale where order_id=@id and (status<>'CLOSED' or refunded_at is not null)",Connection,tx);prior.Parameters.AddWithValue("id",input.OrderId);if((decimal)(await prior.ExecuteScalarAsync(ct))!+input.RefundAmount>total)return Conflict(new{message="退款紀錄合計不可超過原訂單金額。"});
  foreach(var item in items.OrderBy(x=>x.OrderItemId)){await using var check=new NpgsqlCommand("select i.quantity::bigint*i.units_per_sale,coalesce((select sum(a.quantity) from cmepms.after_sale_item a join cmepms.after_sale c on c.id=a.after_sale_id where a.order_item_id=i.id and (c.status<>'CLOSED' or a.restocked_at is not null)),0) from cmepms.order_item i where i.id=@item and i.order_id=@order for update of i",Connection,tx);check.Parameters.AddWithValue("item",item.OrderItemId);check.Parameters.AddWithValue("order",input.OrderId);await using var r=await check.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct)||r.GetInt64(1)+item.Quantity>r.GetInt64(0))return Conflict(new{message="售後商品不存在，或數量超過訂購數量。"});}
  await using var insert=new NpgsqlCommand("insert into cmepms.after_sale(order_id,reason,status,refund_amount,created_by) values(@order,@reason,'OPEN',@amount,@by) returning id",Connection,tx);insert.Parameters.AddWithValue("order",input.OrderId);insert.Parameters.AddWithValue("reason",reason);insert.Parameters.AddWithValue("amount",input.RefundAmount);insert.Parameters.AddWithValue("by",admin);var id=(long)(await insert.ExecuteScalarAsync(ct))!;
  foreach(var item in items){await using var line=new NpgsqlCommand("insert into cmepms.after_sale_item(after_sale_id,order_item_id,quantity) values(@case,@item,@quantity)",Connection,tx);line.Parameters.AddWithValue("case",id);line.Parameters.AddWithValue("item",item.OrderItemId);line.Parameters.AddWithValue("quantity",item.Quantity);await line.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return Ok(new{id});
 }

 [HttpPut("{id:long}/status")]
 public async Task<IActionResult> Status(long id,StatusInput input,CancellationToken ct){if(!Guid.TryParse(User.FindFirstValue("sub"),out var admin))return Unauthorized();if(input.Status is not ("RECEIVED" or "REFUNDED" or "CLOSED"))return BadRequest();await Connection.OpenAsync(ct);await using var tx=await Connection.BeginTransactionAsync(ct);await using var cmd=new NpgsqlCommand("update cmepms.after_sale set status=@status,upd_date=now(),received_at=case when @status='RECEIVED' then now() else received_at end,received_by=case when @status='RECEIVED' then @admin else received_by end,refunded_at=case when @status='REFUNDED' then now() else refunded_at end,refunded_by=case when @status='REFUNDED' then @admin else refunded_by end where id=@id and ((status='OPEN' and @status in ('RECEIVED','CLOSED')) or (status='OPEN' and @status='REFUNDED' and not exists(select 1 from cmepms.after_sale_item where after_sale_id=@id)) or (status='RECEIVED' and @status in ('REFUNDED','CLOSED')) or (status='REFUNDED' and @status='CLOSED')) returning id",Connection,tx);cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("status",input.Status);cmd.Parameters.AddWithValue("admin",admin);if(await cmd.ExecuteScalarAsync(ct) is null)return Conflict(new{message="售後狀態已變更或不允許此操作。"});await tx.CommitAsync(ct);return NoContent();}

 [HttpPost("{id:long}/items/{itemId:long}/restock")]
 public async Task<IActionResult> Restock(long id,long itemId,CancellationToken ct){if(!Guid.TryParse(User.FindFirstValue("sub"),out var admin))return Unauthorized();await Connection.OpenAsync(ct);await using var tx=await Connection.BeginTransactionAsync(ct);await using(var order=new NpgsqlCommand("select coalesce(o.stat,'') from cmepms.orders o join cmepms.after_sale a on a.order_id=o.id where a.id=@id for update of o",Connection,tx)){order.Parameters.AddWithValue("id",id);var status=await order.ExecuteScalarAsync(ct) as string;if(status is null)return NotFound();if(status=="ZZ")return Conflict(new{message="訂單已取消並回補庫存，不可重複回補。"});}await using var cmd=new NpgsqlCommand("select a.status,x.restocked_at,x.quantity,i.inventory_id from cmepms.after_sale a join cmepms.after_sale_item x on x.after_sale_id=a.id join cmepms.order_item i on i.id=x.order_item_id where a.id=@id and x.id=@item for update of a,x",Connection,tx);cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("item",itemId);long sku;int quantity;await using(var r=await cmd.ExecuteReaderAsync(ct)){if(!await r.ReadAsync(ct))return NotFound();if(r.GetString(0) is not ("RECEIVED" or "REFUNDED")||!r.IsDBNull(1))return Conflict(new{message="請先確認收貨，且不可重複回補。"});quantity=r.GetInt32(2);sku=r.GetInt64(3);}await using var stock=new NpgsqlCommand("update cmepms.product_inventory set stock_qty=stock_qty+@qty,upd_date=now() where id=@sku",Connection,tx);stock.Parameters.AddWithValue("qty",quantity);stock.Parameters.AddWithValue("sku",sku);if(await stock.ExecuteNonQueryAsync(ct)!=1)throw new InvalidOperationException("商品規格不存在。");await using var mark=new NpgsqlCommand("update cmepms.after_sale_item set restocked_at=now(),restocked_by=@admin where id=@id",Connection,tx);mark.Parameters.AddWithValue("admin",admin);mark.Parameters.AddWithValue("id",itemId);await mark.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);return NoContent();}
}
